/**
 * @file Holds what a select or autocomplete has selected.
 *
 * The selected options live in `state.selected` as `{ value, label }`, which is what the chips render and what the hidden inputs submit. The DOM says the same thing through `aria-selected`, and both are written in the same pass.
 */
import { omitEmpty } from '@splendidlabz/utils'
import { addListeners, removeListeners } from '@splendidlabz/utils/dom'
import {
  closeCombobox,
  commitSelection,
  highlight,
  initCombobox,
  isComboboxOpen,
  openCombobox,
  stopClosingCombobox,
} from './combobox.svelte.js'
import {
  getAdjacentOption,
  getAllOptions,
  getHighlightedOption,
  getOptionStartingWith,
  getVisibleOptions,
} from './listbox.js'

/**
 * @import { Combobox } from './combobox.svelte.js'
 */

// ========================================
// Actions
// ========================================
/**
 * selectTrigger
 * Lets a button open its options, select them, and jump to one by typing its first letters.
 *
 * `comboboxInput` runs first on the same button. A key it already handled arrives prevented and is left alone, so an Enter that selected an option doesn't open the list again.
 *
 * @see https://www.w3.org/WAI/ARIA/apg/patterns/combobox/examples/combobox-select-only/
 *
 * @param {HTMLButtonElement} node
 * @param {object} [props]
 * @param {object} [props.options]
 * @param {(item: any) => void} [props.options.onselect] Receives the item, or the option element
 * @param {boolean} [props.options.multiple] Let more than one option be selected
 * @param {number} [props.options.max] Most options a multi select takes
 * @param {SelectEntry | SelectEntry[] | null} [props.options.selected] Selection to start with
 */
export function selectTrigger(node, props = {}) {
  const id = /** @type {string} */ (node.getAttribute('target'))
  let onselect = props.options?.onselect

  const combobox = initSelection({
    id,
    options: props.options,
    onselect: selectItem,
  })

  let typedText = ''
  /** @type {ReturnType<typeof setTimeout> | undefined} */
  let typingTimer

  // On the box, not the button: chips share the field with the button, so a gesture that starts or ends on one still belongs to the field.
  const box = node.closest('.input-group') ?? node

  const listeners = [
    { event: 'keydown', node, handler: onKeydown },
    { event: 'keyup', node, handler: preventSpaceClick },
    { event: 'pointerdown', node: box, handler: onPointerdown },
    { event: 'pointerup', node: box, handler: onPointerup },
  ]

  addListeners(listeners)

  return {
    /**
     * update
     * Takes the button's new options.
     *
     * @param {typeof props} [nextProps]
     */
    update(nextProps = {}) {
      onselect = nextProps.options?.onselect
      Object.assign(combobox.options, omitEmpty(nextProps.options), {
        onselect: selectItem,
      })
    },
    destroy() {
      removeListeners(listeners)
      clearTimeout(typingTimer)
    },
  }

  /**
   * selectItem
   * Records the selection, then hands the item back to whoever owns it.
   *
   * @param {HTMLElement} option
   */
  function selectItem(option) {
    toggleSelected(combobox, getOptionData(option))
    sendItem({ combobox, option, onselect })
  }

  /**
   * onKeydown
   * Opens the list and selects from it, jumps to either end, and jumps to typed text.
   *
   * @param {KeyboardEvent} event
   */
  function onKeydown(event) {
    const { listbox } = combobox.nodes
    if (event.defaultPrevented || !listbox) return

    const { key } = event
    const isOpen = isComboboxOpen(combobox)

    // A space typed right after other characters is part of the typed text
    if (key === ' ' && typedText) return jumpToTypedText(event)

    if (key === 'Enter' || key === ' ') {
      event.preventDefault()
      if (!isOpen) return openList()

      const option = getHighlightedOption(listbox)
      if (option) commitSelection(combobox, option)
      return
    }

    if ((key === 'Home' || key === 'End') && isOpen) {
      event.preventDefault()
      const options = getVisibleOptions(listbox)
      highlight(combobox, options[key === 'Home' ? 0 : options.length - 1], {
        behaviour: 'instant',
      })
      return
    }

    const isCharacter =
      key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey
    if (isCharacter) jumpToTypedText(event)
  }

  /**
   * jumpToTypedText
   * Opens the list and highlights the option starting with what was typed in the last 500ms. The same character again moves on to the next option starting with it.
   *
   * @param {KeyboardEvent} event
   */
  function jumpToTypedText(event) {
    event.preventDefault()

    clearTimeout(typingTimer)
    typingTimer = setTimeout(() => (typedText = ''), 500)
    typedText += event.key

    // Typed text means the options are wanted, so it also ends a close still fading
    stopClosingCombobox(combobox)
    if (!isComboboxOpen(combobox)) openList()

    const { listbox } = combobox.nodes
    const isRepeat = [...typedText].every(char => char === typedText[0])
    const option = isRepeat
      ? getOptionStartingWith({
          listbox,
          text: typedText[0],
          from: getAdjacentOption({ listbox, direction: 'next', loop: true }),
        })
      : getOptionStartingWith({
          listbox,
          text: typedText,
          from: getHighlightedOption(listbox),
        })

    if (option) highlight(combobox, option, { behaviour: 'smooth' })
  }

  /**
   * openList
   * Opens the options, with the selected option highlighted.
   */
  function openList() {
    openCombobox(combobox)

    const [firstSelected] = combobox.state.selected
    if (!firstSelected) return

    const option = getOptionByValue({ combobox, value: firstSelected.value })
    if (option) highlight(combobox, option, { behaviour: 'instant' })
  }

  /**
   * onPointerdown
   * Opens or closes the options the moment a mouse presses the box, the way a native select does.
   *
   * @param {PointerEvent} event
   */
  function onPointerdown(event) {
    if (event.pointerType !== 'mouse') return

    // Safari takes focus off a pressed button, and that focusout closes the list before the gesture finishes
    event.preventDefault()
    toggleList(event)
  }

  /**
   * onPointerup
   * Opens or closes the options on a tap. A pen or a finger has to lift before it counts, so a scroll that starts on the box ends in `pointercancel` and leaves the list alone.
   *
   * @param {PointerEvent} event
   */
  function onPointerup(event) {
    if (event.pointerType === 'mouse') return
    toggleList(event)
  }

  /**
   * toggleList
   * Opens or closes the options.
   *
   * @param {PointerEvent} event
   */
  function toggleList(event) {
    // A chip's remove button sits in the box and answers its own press
    if (
      /** @type {HTMLElement} */ (event.target).closest('.chip-remove-button')
    )
      return

    // Safari doesn't focus a pressed button, and Escape and clicking away need focus
    node.focus()

    // A press on a list still fading closes it rather than bringing it back
    if (combobox.state.phase === 'closed') openList()
    else closeCombobox(combobox)
  }

  /**
   * preventSpaceClick
   * Stops Space from clicking the button once keydown has used it.
   *
   * @param {KeyboardEvent} event
   */
  function preventSpaceClick(event) {
    if (event.key === ' ') event.preventDefault()
  }
}

/**
 * selectOptions
 * Registers the items the options were rendered from, so selecting one can return the original.
 *
 * @param {HTMLElement} node Wrapper holding the listbox
 * @param {object} [props]
 * @param {any[]} [props.items]
 */
export function selectOptions(node, props = {}) {
  const combobox = initCombobox({
    id: node.id,
    state: { items: props.items },
  })

  applySelection(combobox)

  return {
    /**
     * update
     * Takes the new items, and marks the options holding a selected value.
     *
     * @param {typeof props} [nextProps]
     */
    update(nextProps = {}) {
      combobox.state.items = nextProps.items
      applySelection(combobox)
    },
  }
}

// ========================================
// Methods
// ========================================
/**
 * initSelection
 * Registers the selection a select or autocomplete starts with, and the options its input part was given.
 *
 * @param {object} opts
 * @param {string} opts.id Id of the options wrapper
 * @param {object} [opts.state]
 * @param {Record<string, any>} [opts.options] Options for the input part
 * @param {Record<string, any>} [opts.defaults] Defaults for those options
 * @param {(option: HTMLElement) => void} opts.onselect Receives the chosen option
 * @returns {Combobox}
 */
export function initSelection({ id, state, options, defaults, onselect }) {
  const combobox = initCombobox({
    id,
    state,
    options: { ...defaults, ...omitEmpty(options), onselect },
  })

  // An empty array doesn't survive the merge into a registered part, so it's written here
  combobox.state.selected ??= toSelectedOptions(options?.selected)

  // The options can register first, before the selection was known
  applySelection(combobox)

  // The binding gets the selection in the shape of the mode from the start
  sendSelected(combobox)
  return combobox
}

/**
 * getValueAndLabel
 * Reads an item or a selected entry. A bare string is both value and label, and a missing value falls back to the label.
 *
 * @typedef {{ value: string, label: string }} SelectedOption
 * @typedef {string | { value?: string, label: string }} SelectEntry An item, or a selected option passed in.
 *
 * @param {SelectEntry} entry
 * @returns {SelectedOption}
 */
export function getValueAndLabel(entry) {
  if (typeof entry === 'string') return { value: entry, label: entry }
  return { value: entry.value ?? entry.label, label: entry.label }
}

/**
 * toSelectedOptions
 * Reads the `selected` prop into a list: one entry for a single select, an array for a multi select.
 *
 * @param {SelectEntry | SelectEntry[] | null} [selected]
 * @returns {SelectedOption[]}
 */
export function toSelectedOptions(selected) {
  if (!selected) return []
  if (!Array.isArray(selected)) return [getValueAndLabel(selected)]
  return selected.map(getValueAndLabel)
}

/**
 * getOptionData
 * Reads the value and label an option carries.
 *
 * @param {HTMLElement} option
 * @returns {SelectedOption}
 */
export function getOptionData(option) {
  const { value, label } = /** @type {{ value: string, label?: string }} */ (
    option.dataset
  )
  return { value, label: label ?? value ?? '' }
}

/**
 * sendItem
 * Hands the chosen item to the caller's `onselect`: the original item when options came from `items`, or else the option element.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {HTMLElement} opts.option
 * @param {(item: any) => void} [opts.onselect]
 * @returns {void}
 */
export function sendItem({ combobox, option, onselect }) {
  if (!onselect) return

  const { index } = option.dataset
  if (index === undefined) return onselect(option)
  onselect($state.snapshot(combobox.state.items[Number(index)]))
}

/**
 * canSelectOption
 * Reads whether an option can still be chosen. A full multi select refuses a new option, and still lets a chosen one be taken off.
 *
 * @param {Combobox} combobox
 * @param {HTMLElement} option
 * @returns {boolean}
 */
export function canSelectOption(combobox, option) {
  const { max, multiple } = combobox.options
  if (!multiple || !max) return true
  if (isSelected({ combobox, value: getOptionData(option).value })) return true
  return combobox.state.selected.length < max
}

/**
 * toggleSelected
 * Selects an option. In a multi select, an option already selected is deselected instead.
 *
 * @param {Combobox} combobox
 * @param {SelectedOption} selectedOption
 * @returns {void}
 */
export function toggleSelected(combobox, selectedOption) {
  const { value } = selectedOption
  if (combobox.options.multiple && isSelected({ combobox, value }))
    return deselect({ combobox, value })
  addSelected(combobox, selectedOption)
}

/**
 * addSelected
 * Adds a selected option. A single select holds one, so the new one replaces it.
 *
 * @param {Combobox} combobox
 * @param {SelectedOption} selectedOption
 * @returns {void}
 */
export function addSelected(combobox, selectedOption) {
  if (combobox.options.multiple) combobox.state.selected.push(selectedOption)
  else combobox.state.selected = [selectedOption]
  applySelection(combobox)
  sendSelected(combobox)
}

/**
 * deselect
 * Takes a value off the selection, and off the option holding it.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string} opts.value
 * @returns {void}
 */
export function deselect({ combobox, value }) {
  const index = combobox.state.selected.findIndex(
    /** @param {SelectedOption} selectedOption */
    selectedOption =>
      isSameValue({ combobox, one: selectedOption.value, other: value }),
  )
  if (index === -1) return

  combobox.state.selected.splice(index, 1)
  getOptionByValue({ combobox, value })?.setAttribute('aria-selected', 'false')
  applySelection(combobox)
  sendSelected(combobox)
}

/**
 * isSelected
 * Reads whether a value is already selected.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string} opts.value
 * @returns {boolean}
 */
export function isSelected({ combobox, value }) {
  return combobox.state.selected.some(
    /** @param {SelectedOption} selectedOption */
    selectedOption =>
      isSameValue({ combobox, one: selectedOption.value, other: value }),
  )
}

/**
 * getOptionByValue
 * Gets the option holding a value.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string} opts.value
 * @returns {HTMLElement | null}
 */
export function getOptionByValue({ combobox, value }) {
  const options = getAllOptions(combobox.nodes.listbox)
  return (
    options.find(option =>
      isSameValue({ combobox, one: option.dataset.value, other: value }),
    ) ?? null
  )
}

/**
 * sendSelected
 * Hands the selection to `onselectedchange`: one option or `null` for a single select, an array for a multi select.
 *
 * @param {Combobox} combobox
 * @returns {void}
 */
function sendSelected(combobox) {
  const copies = combobox.state.selected.map(
    /** @param {SelectedOption} option */ option => ({ ...option }),
  )
  combobox.options.onselectedchange?.(
    combobox.options.multiple ? copies : (copies[0] ?? null),
  )
}

/**
 * applySelection
 * Writes the selection onto the options: which ones are selected, and which ones a full selection refuses.
 *
 * @param {Combobox} combobox
 * @returns {void}
 */
function applySelection(combobox) {
  const { listbox } = combobox.nodes
  if (!listbox || !combobox.state.selected) return

  for (const selectedOption of combobox.state.selected) {
    getOptionByValue({ combobox, value: selectedOption.value })?.setAttribute(
      'aria-selected',
      'true',
    )
  }

  const { max, multiple } = combobox.options
  if (!multiple || !max) return

  const isFull = combobox.state.selected.length >= max
  for (const option of getAllOptions(listbox)) {
    const isRefused = isFull && option.getAttribute('aria-selected') !== 'true'
    if (isRefused) option.setAttribute('aria-disabled', 'true')
    else option.removeAttribute('aria-disabled')
  }
}

/**
 * isSameValue
 * Compares two values the way this select matches text.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string} [opts.one]
 * @param {string} [opts.other]
 * @returns {boolean}
 */
function isSameValue({ combobox, one, other }) {
  if (one === undefined || other === undefined) return false
  if (combobox.options.caseSensitive) return one.trim() === other.trim()
  return one.trim().toLowerCase() === other.trim().toLowerCase()
}
